import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { authAPI } from '../api/api';
import { useAuth } from '../context/AuthContext';

export default function Login() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(''); setLoading(true);
    try {
      const res = await authAPI.login(form);
      login(res.data);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Invalid credentials');
    } finally { setLoading(false); }
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <h2 style={styles.title}>Welcome Back 👋</h2>
        <p style={styles.sub}>Sign in to continue learning</p>
        {error && <div style={styles.error}>{error}</div>}
        <form onSubmit={handleSubmit}>
          <input style={styles.input} type="email" placeholder="Email" value={form.email}
            onChange={e => setForm({ ...form, email: e.target.value })} required />
          <input style={styles.input} type="password" placeholder="Password" value={form.password}
            onChange={e => setForm({ ...form, password: e.target.value })} required />
          <button style={styles.btn} type="submit" disabled={loading}>
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>
        <p style={styles.footer}>Don't have an account? <Link to="/register" style={styles.link}>Register</Link></p>
      </div>
    </div>
  );
}

const styleTag = document.createElement('style');
styleTag.innerHTML = `@keyframes gradientShift { 0%{background-position:0% 50%} 50%{background-position:100% 50%} 100%{background-position:0% 50%} }`;
document.head.appendChild(styleTag);

const styles = {
  page: { minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center', background:'linear-gradient(135deg, #1a1a2e 0%, #16213e 40%, #0f3460 70%, #e94560 100%)', backgroundSize:'400% 400%', animation:'gradientShift 8s ease infinite' },
  card: { background:'#fff', borderRadius:16, padding:'40px 36px', width:380, boxShadow:'0 20px 60px rgba(0,0,0,0.3)' },
  title: { margin:'0 0 4px', color:'#1a1a2e', fontSize:26 },
  sub: { color:'#888', marginBottom:24, marginTop:0 },
  error: { background:'#fee', color:'#c00', padding:'10px 14px', borderRadius:8, marginBottom:16, fontSize:14 },
  input: { width:'100%', padding:'12px 14px', borderRadius:8, border:'1px solid #ddd', marginBottom:14, fontSize:14, boxSizing:'border-box' },
  btn: { width:'100%', padding:14, background:'#e94560', color:'#fff', border:'none', borderRadius:8, fontSize:15, cursor:'pointer', fontWeight:600 },
  footer: { textAlign:'center', marginTop:20, color:'#888', fontSize:14 },
  link: { color:'#e94560', textDecoration:'none' },
};
